async ({ session: { outline } }) => {
  const o: any = await outline({ previewChars: 80 });
  const entries = o.entries ?? [];
  const byState: Record<string, number> = {};
  for (const e of entries) byState[e.state] = (byState[e.state] ?? 0) + 1;
  const keys = Object.keys(o).filter((k) => k !== "entries");
  return {
    meta: Object.fromEntries(keys.map((k) => [k, o[k]])),
    count: entries.length, byState,
    collapsed: entries.filter((e: any) => String(e.preview).startsWith("[Pit: collapsed")).length,
    roles: entries.map((e: any) => `${e.id}:${e.role}:${e.tokens}`).join(" "),
  };
}
